"""Generate frontend role defaults from the backend's authoritative permission catalogue."""

import argparse
import json
from pathlib import Path

from app.modules.accounts.access import PERMISSIONS, ROLE_DEFAULTS


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    options = json.dumps(list(PERMISSIONS.items()), ensure_ascii=False, indent=2)
    defaults = json.dumps(ROLE_DEFAULTS, ensure_ascii=False, indent=2)
    args.output.write_text(
        "// Generated by BACK/scripts/export_permissions.py. Do not edit.\n"
        + "export const PERMISSION_OPTIONS = "
        + options
        + " as const\n"
        + "export const ROLE_DEFAULTS: Record<string, string[]> = "
        + defaults
        + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
